<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sunfall City</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #0c0a18;
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; }
  #game { position: fixed; inset: 0; width: 100%; height: 100%; display: block; }

  /* ---- start menu: a full-screen overlay, hidden with .hidden once the city opens ---- */
  #menu { position: fixed; inset: 0; z-index: 10; display: flex; flex-direction: column;
    align-items: center; justify-content: center; gap: 22px; text-align: center;
    background: linear-gradient(165deg, #0e0b1e 0%, #191338 55%, #2b1c4e 100%); }
  #menu.hidden { display: none; }
  #menu h1 { font-size: clamp(44px, 9vw, 94px); font-weight: 900; letter-spacing: 0.08em;
    line-height: 1; color: #ffd166; text-shadow: 0 0 26px rgba(255, 209, 102, 0.35); }
  #menu h1 .pink { color: #ef476f; text-shadow: 0 0 26px rgba(239, 71, 111, 0.45); }
  #menu .tagline { color: #9aa0c0; font-size: 13px; letter-spacing: 0.28em; }
  #enter { pointer-events: auto; cursor: pointer; background: #ffd166; color: #1a1433;
    border: none; padding: 15px 44px; font-size: 18px; font-weight: 800; letter-spacing: 0.14em;
    border-radius: 4px; box-shadow: 0 0 30px rgba(255, 209, 102, 0.35); font-family: inherit;
    transition: background 0.15s, transform 0.15s; }
  #enter:hover { background: #ffe29a; transform: translateY(-1px); }
  #menu .controls { list-style: none; color: #8b90b3; font-size: 13px; line-height: 2;
    letter-spacing: 0.04em; }
  #menu .controls b { color: #e8eaf6; display: inline-block; min-width: 66px; text-align: right;
    margin-right: 12px; font-weight: 700; }

  /* ---- hud: built at runtime into the empty #hud div ---- */
  #hud { position: fixed; inset: 0; pointer-events: none; z-index: 5; color: #e8eaf6;
    text-shadow: 0 2px 6px rgba(0, 0, 0, 0.8); }
  #hud .panel { position: absolute; top: 16px; right: 18px; text-align: right; }
  #hud .stars { font-size: 21px; letter-spacing: 4px; color: #3a3f5c; }
  #hud .stars .on { color: #ffd166; text-shadow: 0 0 12px rgba(255, 209, 102, 0.8); }
  #hud .cash { font-size: 24px; font-weight: 800; color: #8ce99a; margin-top: 2px; }
  #hud .healthbar { width: 184px; height: 9px; background: rgba(255, 255, 255, 0.12);
    border-radius: 5px; margin: 8px 0 4px auto; overflow: hidden; }
  #hud .healthbar .fill { height: 100%; width: 100%; background: #ef476f;
    border-radius: 5px; transition: width 0.2s; }
  #hud .mode { font-size: 12px; letter-spacing: 0.18em; color: #9aa0c0; }
  #hud #minimap { position: absolute; left: 16px; bottom: 16px; border-radius: 6px;
    border: 2px solid rgba(255, 255, 255, 0.18); box-shadow: 0 6px 24px rgba(0, 0, 0, 0.5); }
  #hud .objective { position: absolute; left: 50%; bottom: 64px; transform: translateX(-50%);
    max-width: 80vw; text-align: center; font-size: 14px; letter-spacing: 0.06em; color: #ffd166;
    background: rgba(12, 10, 26, 0.72); padding: 6px 14px; border-radius: 4px;
