  #hud .feed { position: absolute; left: 50%; bottom: 100px; transform: translateX(-50%);
    display: flex; flex-direction: column; align-items: center; gap: 4px; }
  #hud .toast { background: rgba(12, 10, 26, 0.72); border-left: 3px solid #ffd166;
