  #hud .toast.out { opacity: 0; }
  #hud .banner { position: absolute; left: 0; right: 0; top: 36%; text-align: center;
    font-size: clamp(40px, 8vw, 80px); font-weight: 900; letter-spacing: 0.18em; color: #ef476f;
    text-shadow: 0 0 40px rgba(239, 71, 111, 0.5), 0 4px 14px rgba(0, 0, 0, 0.8);
    opacity: 0; transition: opacity 0.5s; }
  #hud .banner.show { opacity: 1; }
  #hud .crosshair { position: absolute; top: 50%; left: 50%; width: 14px; height: 14px;
    margin: -7px; border: 2px solid rgba(255, 255, 255, 0.85); border-radius: 50%;
    box-shadow: 0 0 8px rgba(0, 0, 0, 0.6); display: none; }
  #hud .crosshair.on { display: block; }
</style>
